+import { AppServerProcess } from './appServerProcess';
+
+export async function pullThread(threadId: string) {
+  const appServer = new AppServerProcess({ codexBin: 'codex' });
+  await appServer.start({ name: 'inbox', title: 'Inbox', version: '0.1.0' });
+  try {
+    return await appServer.request('thread/read', { threadId, includeTurns: true });
+  } finally {
+    await appServer.stop();
+  }
+}
+
+export function toReplayTurns(thread: any) {
+  return (thread.turns ?? []).map((turn: any) => ({
+    id: turn.id,
+    timestamp: turn.createdAt,
+    items: (turn.items ?? []).map((item: any) => ({
+      id: item.id,
+      type: item.type === 'agentMessage' ? 'assistant' : 'tool',
+      text: item.text ?? undefined,
+      command: Array.isArray(item.command) ? item.command.join(' ') : undefined,
+    })),
+  }));
+}
